from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from django.shortcuts import get_object_or_404
from haystack.query import SearchQuerySet
from .models import LegalPrecedentCase

class SimilarPrecedentCasesView(APIView):
    permission_classes = [IsAuthenticated]

    def get(self, request, case_id):
        case = get_object_or_404(LegalPrecedentCase, id=case_id, firm=request.user.firm)
        sqs = SearchQuerySet().filter(firm_id=request.user.firm_id).more_like_this(case)
        similar = [
            {
                "id": r.pk,
                "docket_number": r.docket_number,
                "ruling_notes": r.ruling_notes
            } for r in sqs[:5]
        ]
        return Response({"case_id": case.id, "similar_cases": similar})
